def _observation_items(
    observation_catalog: Sequence[Mapping[str, object]] | None,
) -> tuple[Mapping[str, object], ...]:
    if observation_catalog is None:
        return ()
    items: list[Mapping[str, object]] = []
    seen: set[str] = set()
    for item in observation_catalog:
        if not isinstance(item, Mapping):
            continue
        name = item.get("name")
        if (
            not isinstance(name, str)
            or item.get("capability_class") != "observation"
            or item.get("available") is not True
            or item.get("ready") is not True
        ):
            continue
        if name in seen:
            raise DecisionParseError(f"duplicate observation capability: {name}")
        seen.add(name)
        items.append(item)
    return tuple(items)


