def _touch_session(self) -> None:
    if not self._session_active:
        return
    self._session_deadline_ns = self._monotonic_ns() + int(
        self._config.session_silence_timeout_s * 1_000_000_000
    )
    self._publish_status()

def _session_expired(self) -> bool:
    if not self._session_active or self._session_deadline_ns is None:
        return False
    return self._monotonic_ns() >= self._session_deadline_ns

def _session_remaining_ms(self) -> float | None:
    if not self._session_active or self._session_deadline_ns is None:
        return None
    return max(
        0.0,
        (self._session_deadline_ns - self._monotonic_ns()) / 1_000_000.0,
    )

def _close_session(self, reason: str) -> None:
    if not self._session_active:
        return
    self._session_active = False
    self._session_deadline_ns = None
